async function run() {
  const rows = [];

  for (const [id, langs] of Object.entries(CATEGORIES)) {
    for (const [lang, fields] of Object.entries(langs)) {
      for (const [field, text] of Object.entries(fields)) {
        rows.push(['category', Number(id), field, lang, text]);
      }
    }
  }

  for (const [id, langs] of Object.entries(DQ)) {
    for (const [lang, fields] of Object.entries(langs)) {
      for (const [field, text] of Object.entries(fields)) {
        rows.push(['daily_question', Number(id), field, lang, text]);
      }
    }
  }

  for (const [id, langs] of Object.entries(LU)) {
    for (const [lang, fields] of Object.entries(langs)) {
      for (const [field, text] of Object.entries(fields)) {
        rows.push(['legal_update', Number(id), field, lang, text]);
      }
    }
  }

  let count = 0;
  for (const row of rows) {
    await pool.execute(
      `
        INSERT INTO translations (entity_type, entity_id, field_name, lang_code, translated_text)
        VALUES (?, ?, ?, ?, ?)
        ON DUPLICATE KEY UPDATE translated_text = VALUES(translated_text)
      `,
      row
    );
    count += 1;
  }

  console.log(`Seeded ${count} translation rows (categories + daily_questions + legal_updates).`);
  await pool.end();
}

run().catch((error) => {
  console.error('Failed to seed translations.');
  console.error(error && error.stack ? error.stack : error);
  process.exit(1);
});
